module friendship_clique (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [7:0] adj [0:7],\n    output reg [3:0] steps,\n    output reg [7:0] sequence [0:7],\n    output reg done\n);\n    \n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH  = 2'd2;\n    \n    reg [1:0] state;\n    reg [2:0] current_guest;\n    reg [7:0] temp_adj [0:7];\n    reg [3:0] step_count;\n    reg [7:0] sequence_reg [0:7];\n    reg [2:0] seq_index;\n    integer i, j;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            steps <= 4'd0;\n            done <= 1'b0;\n            current_guest <= 3'd0;\n            step_count <= 4'd0;\n            seq_index <= 3'd0;\n            for (i = 0; i < 8; i = i +1) begin\n                sequence[i] <= 8'd0;\n                sequence_reg[i] <= 8'd0;\n                temp_adj[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    step_count <= 4'd0;\n                    seq_index <= 3'd0;\n                    current_guest <= 3'd0;\n                    if (start) begin\n                        state <= COMPUTE;\n                        for (i = 0; i < 8; i = i +1) begin\n                            temp_adj[i] <= adj[i];\n                            sequence_reg[i] <= 8'd0;\n                        end\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (is_complete(n)) begin\n                        state <= FINISH;\n                    end else if (current_guest < n) begin\n                        if (has_neighbors(current_guest, n)) begin\n                            sequence_reg[seq_index] <= current_guest + 3'd1;\n                            seq_index <= seq_index + 3'd1;\n                            step_count <= step_count + 4'd1;\n                            for (i = 0; i < n; i = i + 1) begin\n                                if (temp_adj[current_guest][i]) begin\n                                    for (j = i + 1; j < n; j = j + 1) begin\n                                        if (temp_adj[current_guest][j]) begin\n                                            temp_adj[i][j] <= 1'b1;\n                                            temp_adj[j][i] <= 1'b1;\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                        current_guest <= current_guest + 3'd1;\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    steps <= step_count;\n                    for (i = 0; i < 8; i = i +1) sequence[i] <= sequence_reg[i];\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \n    function automatic is_complete;\n        input [2:0] size;\n        begin\n            is_complete = 1'b1;\n            for (i = 0; i < size; i = i +1) begin\n                for (j = i + 1; j < size; j = j +1) begin\n                    if (!temp_adj[i][j]) is_complete = 1'b0;\n                end\n            end\n        end\n    endfunction\n    \n    function automatic has_neighbors;\n        input [2:0] guest;\n        input [2:0] size;\n        begin\n            has_neighbors = 1'b0;\n            for (i = 0; i < size; i = i +1) begin\n                if (temp_adj[guest][i] && (i != guest)) has_neighbors = 1'b1;\n            end\n        end\n    endfunction\nendmodule